// NewRegistry creates a new Registry backed by the given data directory.
func NewRegistry(dataDir string) (*Registry, error) {
        if err := os.MkdirAll(dataDir, 0755); err != nil {
                return nil, fmt.Errorf("create data dir: %w", err)
        }
        r := &Registry{
                models:  make(map[string]*Model),
                dataDir: dataDir,
        }
        if err := r.loadAll(); err != nil {
                return nil, fmt.Errorf("load registry: %w", err)
        }
        return r, nil
}

// RegisterModel creates a new model entry in the registry.
func (r *Registry) RegisterModel(name, framework, description string, tags []string) (*Model, error) {
        r.mu.Lock()
        defer r.mu.Unlock()

        if _, exists := r.models[name]; exists {
                return nil, fmt.Errorf("model %q already exists", name)
        }

        now := time.Now()
        model := &Model{
                Name:        name,
                Framework:   framework,
                Description: description,
                Tags:        tags,
                Versions:    make([]*Version, 0),
                CreatedAt:   now,
                UpdatedAt:   now,
        }
        r.models[name] = model
        if err := r.saveModel(model); err != nil {
                delete(r.models, name)
                return nil, err
        }
        return model, nil
}

// CreateVersion adds a new version to the specified model.
