package api

import (
        "net/http"

        "gomlops/internal/experiment"
        "gomlops/internal/pipeline"
        "gomlops/internal/registry"
        "gomlops/internal/serving"
)

// Handlers holds references to all service components.
type Handlers struct {
        Registry   *registry.Registry
        Pipeline   *pipeline.Engine
        Experiment *experiment.Tracker
        Serving    *serving.Server
}

// NewRouter builds the HTTP route table and returns a handler.
func NewRouter(reg *registry.Registry, eng *pipeline.Engine, tracker *experiment.Tracker, srv *serving.Server) http.Handler {
        h := &Handlers{
                Registry:   reg,
                Pipeline:   eng,
                Experiment: tracker,
                Serving:    srv,
        }

        mux := http.NewServeMux()

        // Model registry endpoints
        mux.HandleFunc("POST /api/v1/models", h.RegisterModel)
        mux.HandleFunc("GET /api/v1/models", h.ListModels)
        mux.HandleFunc("GET /api/v1/models/{name}", h.GetModel)
        mux.HandleFunc("POST /api/v1/models/{name}/versions", h.CreateVersion)
        mux.HandleFunc("GET /api/v1/models/{name}/versions/{num}", h.GetVersion)
        mux.HandleFunc("PUT /api/v1/models/{name}/versions/{num}/promote", h.PromoteVersion)
        mux.HandleFunc("DELETE /api/v1/models/{name}", h.DeleteModel)

        // Pipeline endpoints
        mux.HandleFunc("POST /api/v1/pipelines/execute", h.ExecutePipeline)

        // Experiment endpoints
        mux.HandleFunc("POST /api/v1/experiments", h.CreateExperiment)
        mux.HandleFunc("GET /api/v1/experiments", h.ListExperiments)
        mux.HandleFunc("GET /api/v1/experiments/{name}", h.GetExperiment)
        mux.HandleFunc("POST /api/v1/experiments/{name}/runs", h.LogRun)
        mux.HandleFunc("GET /api/v1/experiments/{name}/metrics/{metric}/aggregate", h.AggregateMetric)

        // Serving endpoints
        mux.HandleFunc("POST /api/v1/serving/load", h.LoadModel)
        mux.HandleFunc("DELETE /api/v1/serving/models/{name}", h.UnloadModel)
        mux.HandleFunc("GET /api/v1/serving/models", h.ListLoadedModels)
        mux.HandleFunc("POST /api/v1/serving/infer", h.Infer)

        // Health check
        mux.HandleFunc("GET /health", func(w http.ResponseWriter, r *http.Request) {
                w.WriteHeader(http.StatusOK)
                w.Write([]byte(`{"status":"ok"}`))
        })

        return mux
}
