func (t *Tracker) AggregateMetric(experimentName, metricName, aggType, weightParam string) (float64, int, error) {
	t.mu.RLock()
	defer t.mu.RUnlock()

	exp, exists := t.experiments[experimentName]
	if !exists {
		return 0, 0, fmt.Errorf("experiment %q not found", experimentName)
	}

	if len(exp.Runs) == 0 {
		return 0, 0, fmt.Errorf("experiment %q has no runs", experimentName)
	}

	var values []float64
	var weights []float64
	for _, run := range exp.Runs {
		value, ok := run.Metrics[metricName]
		if !ok {
			continue
		}
		values = append(values, value)
		if aggType == "weighted_mean" {
			weight, ok := run.Parameters[weightParam]
			if !ok {
				continue
			}
			weights = append(weights, weight)
		}
	}

	if len(values) == 0 {
		return 0, 0, fmt.Errorf("no values found for metric %q", metricName)
	}

	switch aggType {
	case "mean":
		sum := 0.0
		for _, v := range values {
			sum += v
		}
		return sum / float64(len(values)), len(values), nil

	case "median":
		sorted := sortedCopy(values)
		n := len(sorted)
		if n%2 == 0 {
			return (sorted[n/2-1] + sorted[n/2]) / 2, len(values), nil
		}
		return sorted[n/2], len(values), nil

	case "p95":
		sorted := sortedCopy(values)
		return percentile(sorted, 0.95), len(values), nil

	case "p99":
		sorted := sortedCopy(values)
		return percentile(sorted, 0.99), len(values), nil

	case "weighted_mean":
		if weightParam == "" {
			return 0, 0, fmt.Errorf("weighted_mean requires weight parameter")
		}
		if len(weights) == 0 {
			return 0, 0, fmt.Errorf("no runs with metric %q and weight parameter %q", metricName, weightParam)
		}
		if len(weights) != len(values) {
			return 0, 0, fmt.Errorf("mismatch between metric values and weights")
		}
		weightedSum := 0.0
		weightSum := 0.0
		for i, v := range values {
			weightedSum += v * weights[i]
			weightSum += weights[i]
		}
		if weightSum == 0 {
			return 0, 0, fmt.Errorf("weighted_mean has zero total weight")
		}
		return weightedSum / weightSum, len(values), nil

	default:
		return 0, 0, fmt.Errorf("unknown aggregation type %q", aggType)
	}
}
```
